SELECT , u.nickname AS userName, u.mobile AS mobile
t.is_deleted = 0
AND t.user_id = #{q.userId}
AND t.status = #{q.status}
AND (u.nickname LIKE CONCAT('%', #{q.keyword}, '%') OR u.username LIKE CONCAT('%', #{q.keyword}, '%') OR u.mobile LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY t.status DESC, t.balance DESC, t.id DESC

