UPDATE shop_consumer_wallet
SET balance = balance - #{amount},
    frozen_balance = frozen_balance + #{amount}
WHERE user_id = #{userId}
  AND is_deleted = 0
  AND status = 1
  AND balance >= #{amount}

UPDATE shop_consumer_wallet
SET frozen_balance = frozen_balance - #{amount},
    balance = balance + #{amount}
WHERE user_id = #{userId}
  AND is_deleted = 0
  AND frozen_balance >= #{amount}

UPDATE shop_consumer_wallet
SET frozen_balance = frozen_balance - #{amount},
    total_consume = total_consume + #{amount}
WHERE user_id = #{userId}
  AND is_deleted = 0
  AND frozen_balance >= #{amount}

UPDATE shop_consumer_wallet
SET balance = balance + #{amount},
    total_recharge = total_recharge + #{amount}
WHERE user_id = #{userId}
  AND is_deleted = 0

UPDATE shop_consumer_wallet
SET balance = balance - #{amount},
    total_withdraw = total_withdraw + #{amount}
WHERE user_id = #{userId}
  AND is_deleted = 0
  AND status = 1
  AND balance >= #{amount}
